package apidocs

func (d *document) systemAndIdentity() {
	d.op("System", "GET", "/health", "Check process liveness", "", "Probe", 200).public()
	d.op("System", "GET", "/ready", "Check PostgreSQL readiness", "", "Probe", 200).public().success(503, "Probe", "Database not ready: status=not_ready")
	d.op("Identity", "GET", "/api/v1/me", "Get current account and setup status", allAccounts, "Account", 200).note("Returns account metadata, not the full Student profile. setup_required=false is omitted. Pending Students may call this route. Use /me/student-profile for guardians/accommodation.")
	o := d.op("Identity", "POST", "/api/v1/users", "Provision a login account", admin, "ProvisionResult", 201).body("ProvisionAccount").success(200, "ProvisionResult", "Exact successful replay; no second account").fail(409, "conflict or student_invitation_required when invitations are enabled for Student creation.")
	delete(o.responses, "415")
	o.param("header", "Idempotency-Key", "Generate once; preserve the key and identical email/role/password on retry. Separate from invitation request_id.", object{"type": "string", "minLength": 8, "maxLength": 128, "pattern": "^[A-Za-z0-9_-]{8,128}$", "example": "11111111-1111-4111-8111-111111111111"}, true).note("Legacy Admin provisioning. Student registration should use /student-invitations when enabled. Body maximum16KiB. Credentials belong only to HostelHive; do not use university passwords. Provisioning-in-progress returns503 with Retry-After:1.")
	d.op("Identity", "GET", "/api/v1/users", "List accounts", admin, "AccountPage", 200).paging(1000000)
	d.op("Identity", "PATCH", "/api/v1/users/{userID}/role", "Change an account role", admin, "AccountChange", 200).body("ChangeRole").fail(409, "last_active_admin, revocation_pending, provisioning_incomplete or another account-state conflict.").note("Role changes can queue durable Firebase session revocation. Never infer a successful new role from token claims alone.")
	d.op("Identity", "POST", "/api/v1/users/{userID}/deactivate", "Deactivate an account", admin, "AccountChange", 200).success(202, "AccountChange", "Local denial committed; Firebase revocation remains pending").fail(409, "last_active_admin or another account-state conflict.").note("Empty body. Local access is denied immediately; provider revocation may retry in the worker.")
	d.op("Identity", "POST", "/api/v1/users/{userID}/activate", "Reactivate an eligible account", admin, "AccountChange", 200).fail(409, "revocation_pending, provisioning_incomplete, firebase_identity_missing, firebase_identity_mismatch.").note("Empty body. Activation does not bypass invitation password setup or unarchive a profile.")
	d.op("Identity", "POST", "/api/v1/student-invitations", "Register a Student and queue setup invitation", admin, "RegistrationResult", 201).body("RegisterStudent").success(200, "RegistrationResult", "Exact replay: replayed=true").fail(409, "invitation_conflict: duplicate email/index, reservation or changed payload under the same request_id.").note("Requires STUDENT_INVITATIONS_ENABLED=true and configured approved email domains; otherwise503 student_invitations_unavailable. Atomically creates local account/profile/guardians and durable delivery intent. The worker prepares Firebase identity and sends a private password setup email. No password or setup link is returned. Preserve identical request_id/body for uncertain retries. Sent means provider accepted the email request, not mailbox receipt.")
	d.op("Identity", "GET", "/api/v1/student-invitations", "List Student invitations", admin, "InvitationPage", 200).paging(1000000).note("Readable when delivery is disabled; includes safe status metadata only.")
	d.op("Identity", "GET", "/api/v1/student-invitations/{invitationID}", "Get invitation delivery/setup status", admin, "Invitation", 200)
	d.op("Identity", "POST", "/api/v1/student-invitations/{invitationID}/resend", "Request invitation delivery retry", admin, "Invitation", 200).body("ResendInvitation").fail(409, "invitation_conflict: completed, inactive, archived, wrong-role or reused request ID conflict.").fail(429, "invitation_resend_too_soon; Retry-After:300.").note("Separate new request_id per intended resend; retain on retry. Five-minute cooldown for a new send generation. Pending work is not duplicated. No replacement password is assigned to an existing Firebase identity.")
	d.op("Identity", "POST", "/api/v1/student-invitations/import", "Bulk register Students through invitations", admin, "InvitationImportReport", 200).csv("request_id,email,index_no,full_name,faculty,year,contact_phone,guardians").note("Maximum100 records. Per-record outcomes; partial completion is possible. Replay original CSV request UUIDs on uncertain retry. This differs from the existing-account /students/import contract.")
	d.op("Identity", "GET", "/api/v1/student-invitations/import/template", "Download invitation CSV template", admin, "", 200).binary(200, "text/csv")
	d.op("Identity", "POST", "/api/v1/me/setup/complete", "Verify Student password setup completion", student, "SetupResult", 200).fail(409, "setup_not_verified: require recent password sign-in and provider proof of changed bootstrap password.").note("Omit the body completely. Allowed while setup_required=true. After choosing a password on Firebase's hosted email page, freshly sign in with email/password, then send the current token. Refresh alone is insufficient. No new_password field. Repeats preserve setup_completed_at. Eligible legacy Student without invitation returns false/null.")
}

func (d *document) studentsAndStaff() {
	d.op("Students", "PUT", "/api/v1/me/student-profile/image", "Upload or replace own private profile photo", student, "OwnStudentImageResult", 200).upload().fail(404, "Student profile missing or archived.").note("Mobile and web: send raw JPEG or PNG bytes, not multipart or JSON. Maximum5MiB,12 million decoded pixels,4096 pixels per axis. Only the authenticated active, setup-complete Student is targeted; query selectors are rejected. Private R2 required, otherwise503 student_images_unavailable. Failed validation or replacement preserves the current photo. Superseded and orphan objects use durable cleanup. Response contains the authenticated download path, never a public storage URL.")
	d.op("Students", "DELETE", "/api/v1/me/student-profile/image", "Remove own private profile photo", student, "", 204).fail(404, "Student profile missing or archived.").note("Mobile and web. Omit body and query parameters. Repeated removal returns204 for an eligible profile even if no photo remains. Private R2 must be enabled, otherwise503 student_images_unavailable. Removal clears the reference immediately and queues durable storage cleanup. No other profile fields or scan-derived presence are changed.")
	d.op("Students", "GET", "/api/v1/students", "List unarchived Student profiles", staffReaders, "StudentPage", 200).paging(1000000).query("q", object{"type": "string", "maxLength": 200}, "Search name or index number.").query("faculty", object{"type": "string", "maxLength": 120}, "Faculty filter.").query("year", object{"type": "integer", "minimum": 1, "maximum": 10}, "Academic year.")
	d.op("Students", "GET", "/api/v1/students/{studentID}", "Get a Student profile and guardians", staffReaders, "StudentProfile", 200)
	d.op("Students", "POST", "/api/v1/students", "Create profile for an existing Student account", staffReaders, "StudentProfile", 201).body("CreateStudent").fail(409, "duplicate_student or active_student_account_required.").note("Profile only: user_id must identify an existing eligible Student account. It does not create a login or send invitations. Admin invitation registration uses /student-invitations instead.")
	d.op("Students", "PUT", "/api/v1/students/{studentID}", "Update Student profile and guardians", staffReaders, "StudentProfile", 200).body("StudentDetails").fail(409, "").note("Complete profile details replace the editable fields and guardian list. Account email/credentials are managed separately.")
	d.op("Students", "DELETE", "/api/v1/students/{studentID}", "Archive a Student profile", staffReaders, "", 204).fail(409, "").note("Empty body. Soft archive preserves historical data; it is not a permanent delete or Firebase account deletion.")
	d.op("Students", "POST", "/api/v1/students/import", "Bulk import profiles for existing accounts", admin, "StudentImportReport", 200).csv("user_id,index_no,full_name,faculty,year,contact_phone,guardians").note("Maximum500 records, not100. Links existing eligible Student account UUIDs; never creates Firebase identities. Per-record report may be partial. Use the separate invitation CSV for automatic accounts and setup emails.")
	d.op("Students", "GET", "/api/v1/students/import/template", "Download existing-account profile CSV template", admin, "", 200).binary(200, "text/csv")
	d.op("Students", "PUT", "/api/v1/students/{studentID}/image", "Upload or replace private profile photo", staffReaders, "StudentProfile", 200).upload().fail(409, "").note("Private R2 must be configured;503 student_images_unavailable when disabled. No public R2 URL. A decoded image must contain at most12 million pixels and maximum4096 on each axis; server validates and normalizes image content.")
	d.op("Students", "GET", "/api/v1/students/{studentID}/image", "Download private Student photo", staffReaders, "", 200).binary(200, "image/jpeg", "image/png").note("404 if no photo. Authenticated bytes; do not open as a public URL.")
	d.op("Students", "DELETE", "/api/v1/students/{studentID}/image", "Remove private Student photo", staffReaders, "", 204).note("Empty body. Storage cleanup is queued durably.")
	d.op("Students", "GET", "/api/v1/students/{studentID}/qr", "Download Student QR PNG", staffReaders, "", 200).binary(200, "image/png").fail(409, "active_student_required: ineligible Student profile/account.").note("PNG contains an opaque QR payload; UUID is not a substitute. QR remains stable until the existing lifecycle changes eligibility.")
	d.op("Students", "GET", "/api/v1/me/qr", "Download own Student QR PNG", student, "", 200).binary(200, "image/png").fail(409, "active_student_required.")
	d.op("Students", "GET", "/api/v1/me/student-profile", "Get own profile, guardians, accommodation and presence", student, "OwnStudentProfile", 200).note("No account/Student selectors or query. accommodation=null when no active bed; profile_image_url=null when missing. guardians include name, relationship and contact_phone. Presence is IN/OUT/UNKNOWN from scans. faculty exists; department does not.")
	d.op("Students", "PATCH", "/api/v1/me/student-profile", "Edit own contact phone and guardian details", student, "OwnStudentProfile", 200).body("PatchOwnStudentProfile").fail(404, "not_found: no unarchived Student profile.").fail(413, "payload_too_large: maximum16KiB JSON.").note("Available to authenticated Student clients on mobile or web; no platform-based authorization. Identity is derived from the current account. Only contact_phone and guardians are accepted; at least one must be supplied. Omitted fields stay unchanged. Guardians is a complete replacement list (1-10), not per-guardian PATCH; do not send guardian_id. Explicit null, empty object, unknown fields, duplicate JSON keys and every query parameter are rejected. Input is trimmed and validated. Staff-managed identity, academic, photo, allocation, email, role and scanned presence are never editable here. Updates are atomic and return the same safe aggregate as GET; phone-only edits preserve guardian IDs. Existing Admin/Warden PUT remains unchanged. No email/password changes or attendance actions occur.")
	d.op("Students", "GET", "/api/v1/me/student-profile/image", "Download own private profile photo", student, "", 200).binary(200, "image/jpeg", "image/png").note("404 for missing profile/photo as applicable. Authenticated download; selectors and GET bodies are rejected.")
	d.op("Staff", "GET", "/api/v1/staff", "List staff profiles", admin, "StaffPage", 200).paging(100000)
	d.op("Staff", "GET", "/api/v1/staff/{userID}", "Get staff profile by account UUID", admin, "StaffProfile", 200)
	d.op("Staff", "PUT", "/api/v1/staff/{userID}", "Create or update eligible staff profile", admin, "StaffProfile", 200).body("StaffDetails").fail(409, "staff_account_required: target must have an active eligible staff account.")
	d.op("Staff", "PUT", "/api/v1/staff/me", "Update own staff name", "admin,warden,sub_warden,security_staff", "StaffProfile", 200).body("SelfStaffDetails").note("Only full_name is accepted; cannot change designation, role or another account.")
}

func (d *document) inventoryAndAllocation() {
	d.op("Inventory", "GET", "/api/v1/blocks", "List blocks and capacity", staffReaders, "BlockPage", 200).paging(100000)
	d.op("Inventory", "GET", "/api/v1/rooms", "List rooms and capacity", staffReaders, "RoomPage", 200).paging(100000).query("block_id", uuidQuery(), "Filter by block.")
	d.op("Inventory", "GET", "/api/v1/beds", "List beds and availability", staffReaders, "BedPage", 200).paging(100000).query("block_id", uuidQuery(), "Filter by block.").query("room_id", uuidQuery(), "Filter by room.").query("available", object{"type": "boolean"}, "Filter by current availability.")
	d.op("Inventory", "POST", "/api/v1/blocks", "Create block", admin, "Block", 201).body("BlockDetails").fail(409, "Duplicate block name.")
	d.op("Inventory", "PUT", "/api/v1/blocks/{blockID}", "Rename block", admin, "Block", 200).body("BlockDetails").fail(409, "Duplicate block name.")
	d.op("Inventory", "POST", "/api/v1/rooms", "Create room in block", admin, "Room", 201).body("CreateRoom").fail(404, "").fail(409, "Duplicate room number within block.")
	d.op("Inventory", "PUT", "/api/v1/rooms/{roomID}", "Rename room", admin, "Room", 200).body("RoomDetails").fail(409, "Duplicate room number within block.")
	d.op("Inventory", "POST", "/api/v1/beds", "Create bed in room", admin, "Bed", 201).body("CreateBed").fail(404, "").fail(409, "Duplicate bed number within room.")
	d.op("Inventory", "PUT", "/api/v1/beds/{bedID}", "Rename bed", admin, "Bed", 200).body("BedDetails").fail(409, "Duplicate bed number within room.")
	d.op("Allocation", "GET", "/api/v1/allocations", "List accommodation assignment history", staffReaders, "AllocationPage", 200).paging(100000).query("student_id", uuidQuery(), "Student profile filter.").query("bed_id", uuidQuery(), "Bed filter.").query("active", object{"type": "boolean"}, "True for active allocations, false for ended, omit for both.")
	d.op("Allocation", "POST", "/api/v1/allocations", "Assign an available bed", staffReaders, "Allocation", 201).body("AssignBed").fail(404, "").fail(409, "Student or bed already allocated, or ineligible Student.").note("One active bed per Student and one active occupant per bed; checked transactionally. Does not change scanned presence.")
	d.op("Allocation", "POST", "/api/v1/allocations/{allocationID}/transfer", "Transfer an active allocation to another bed", staffReaders, "Allocation", 200).body("TransferBed").fail(409, "").note("Ends old allocation and returns the new allocation; history remains auditable.")
	d.op("Allocation", "POST", "/api/v1/allocations/{allocationID}/revoke", "Revoke active bed allocation", staffReaders, "Allocation", 200).fail(409, "").note("Empty body. Ends allocation; preserves history and does not change attendance.")
}
